// vectors.rs: golden test vectors for the attention contract.
//
// `docs/superpowers/specs/attention-test-vectors.json` is GENERATED by this
// file from TA's own code (the digest function, the summary shaper and the
// real assertion verifier's claim model), so another system that signs and
// relays assertions can check itself against TA without a running install.
//
// Two tests keep it honest:
//   * `committed_vectors_file_equals_generated_output` fails when the committed
//     file drifts from what this code generates. Regenerate with
//     `TA_REGENERATE_VECTORS=1 ./dev cargo test -p ta-daemon attention::vectors`
//     and commit the result.
//   * `every_vector_runs_through_the_real_verifier` loads the committed file and
//     runs every active vector through `Ed25519RegistryVerifier`, requiring the
//     exact expected outcome and refusal `reason`. The expectations are written
//     here by hand, never read back from the verifier, so a verifier change that
//     alters a decision fails a vector instead of silently rewriting it.
//
// The key pair is TEST ONLY. Nothing here touches a real Keychain or the real
// user state directory: every vector runs in a `tempfile` directory.

use super::*;
use crate::assertion::testkit::TestSigner;
use crate::assertion::{AssertionRequest, AssertionVerifier, Ed25519RegistryVerifier, ItemFacts};

const VECTORS_REL: &str = "../../docs/superpowers/specs/attention-test-vectors.json";
const REGEN_ENV: &str = "TA_REGENERATE_VECTORS";
const NOW: i64 = 1_800_000_000;
const INSTALL_ID: &str = "ta_install_0123456789abcdef0123456789abcdef";
const OTHER_INSTALL_ID: &str = "ta_install_ffffffffffffffffffffffffffffffff";
const KID: &str = "org-1";
const REPO: &str = "wayfinder-demo";

/// Required coverage: a vector set missing any of these is a bug in this file.
const REQUIRED_REASONS: &[&str] = &[
    "expired",
    "not_yet_valid",
    "bad_lifetime",
    "replayed",
    "wrong_audience",
    "item_changed",
    "claim_mismatch",
    "answer_changed",
    "assertion_rejected",
    "self_approval",
    "not_permitted",
];

fn test_seed() -> [u8; 32] {
    let mut seed = [0u8; 32];
    for (i, b) in seed.iter_mut().enumerate() {
        *b = (i + 1) as u8;
    }
    seed
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn vectors_path() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join(VECTORS_REL)
}

// ── Items ───────────────────────────────────────────────────────────────────

struct ItemDef {
    name: &'static str,
    id: &'static str,
    kind: AttentionKind,
    summary_input: String,
    provenance: Option<FeedProvenance>,
    actions: Vec<String>,
}

impl ItemDef {
    fn summary(&self) -> String {
        one_line(&self.summary_input)
    }

    fn digest(&self) -> String {
        item_digest(
            self.id,
            self.kind,
            &self.summary(),
            &self.provenance,
            &self.actions,
        )
    }

    fn digest_with_summary(&self, summary: &str) -> String {
        item_digest(self.id, self.kind, summary, &self.provenance, &self.actions)
    }

    fn requester_id(&self) -> Option<String> {
        self.provenance.as_ref().map(|p| p.requester.id.clone())
    }

    fn to_json(&self) -> Value {
        let summary = self.summary();
        let canonical = canonical_json(&digest_input(
            self.id,
            self.kind,
            &summary,
            &self.provenance,
            &self.actions,
        ));
        let mut v = json!({
            "name": self.name,
            "id": self.id,
            "kind": self.kind.as_str(),
            "summary": summary,
            "summary_chars": summary.chars().count(),
            "provenance": self.provenance,
            "actions": self.actions,
            "canonical_json": canonical,
            "item_digest": self.digest(),
        });
        if summary != self.summary_input {
            v["summary_input"] = json!(self.summary_input);
            v["summary_input_chars"] = json!(self.summary_input.chars().count());
        }
        v
    }
}

fn provenance(excerpt: Option<&str>) -> FeedProvenance {
    FeedProvenance {
        requester: FeedRequester {
            id: "user-123".into(),
            display_name: Some("Michael".into()),
            channel: "wayfinder cos chat".into(),
        },
        excerpt: excerpt.map(|t| FeedExcerpt {
            text: t.into(),
            untrusted: true,
            truncated: false,
        }),
        reason: Some("The task asks for a one-line file.".into()),
        objective: Some("Create notes/live-run6.md".into()),
        chain: FeedChain {
            candidate_id: Some("wayfinder-task:939b7d40#9d23c037".into()),
            cos_goal_id: Some("ea60c2dc-0000-4000-8000-000000000001".into()),
            worker_goal_id: Some("066e4e44-0000-4000-8000-000000000002".into()),
        },
    }
}

fn draft(
    name: &'static str,
    id: &'static str,
    summary: &str,
    provenance: Option<FeedProvenance>,
) -> ItemDef {
    ItemDef {
        name,
        id,
        kind: AttentionKind::DraftReview,
        summary_input: summary.to_string(),
        provenance,
        actions: vec!["review".into(), "approve".into(), "deny".into()],
    }
}

fn items() -> Vec<ItemDef> {
    let base = "Add notes/live-run6.md (CoS delegate implement 066e4e44)";
    // The same visible text twice: precomposed (NFC) and decomposed (NFD).
    let nfc = "Review Caf\u{e9} menu: r\u{e9}sum\u{e9} \u{65e5}\u{672c}\u{8a9e} \u{1f389}";
    let nfd = "Review Cafe\u{301} menu: re\u{301}sume\u{301} \u{65e5}\u{672c}\u{8a9e} \u{1f389}";
    let ten = "abcdefghij";
    vec![
        draft(
            "draft_review_with_provenance",
            "att_draft_352838d8",
            base,
            Some(provenance(Some("Please add a notes file for run 6."))),
        ),
        draft(
            "draft_review_provenance_null",
            "att_draft_0b1c2d3e",
            base,
            None,
        ),
        draft(
            "draft_review_empty_excerpt",
            "att_draft_5e6f7a8b",
            base,
            Some(provenance(Some(""))),
        ),
        ItemDef {
            name: "agent_question",
            id: "att_question_7a1f3c20",
            kind: AttentionKind::AgentQuestion,
            summary_input: "Which branch should the notes file go on?".into(),
            provenance: Some(provenance(Some("Add the notes file, ask me if unsure."))),
            actions: vec!["answer".into()],
        },
        draft("unicode_summary_nfc", "att_draft_unicode_nfc", nfc, None),
        draft("unicode_summary_nfd", "att_draft_unicode_nfd", nfd, None),
        draft(
            "summary_exactly_280_chars",
            "att_draft_len280",
            &ten.repeat(28),
            None,
        ),
        draft(
            "summary_281_chars_truncated",
            "att_draft_len281",
            &format!("{}k", ten.repeat(28)),
            None,
        ),
    ]
}

fn item<'a>(all: &'a [ItemDef], name: &str) -> &'a ItemDef {
    all.iter()
        .find(|i| i.name == name)
        .unwrap_or_else(|| panic!("vector generator references unknown item '{name}'"))
}

// ── Vectors ─────────────────────────────────────────────────────────────────

#[derive(Clone)]
struct KeySpec {
    kid: &'static str,
    maintainer_roles: Vec<&'static str>,
    role_order: Vec<&'static str>,
    escalation_min_role: &'static str,
}

impl KeySpec {
    fn default_key() -> Self {
        Self {
            kid: KID,
            maintainer_roles: vec!["admin", "owner"],
            role_order: vec!["member", "admin", "owner"],
            escalation_min_role: "member",
        }
    }

    fn custom_order() -> Self {
        Self {
            kid: "org-custom",
            maintainer_roles: vec!["lead"],
            role_order: vec!["viewer", "editor", "lead"],
            escalation_min_role: "editor",
        }
    }

    fn to_json(&self) -> Value {
        json!({
            "kid": self.kid,
            "maintainer_roles": self.maintainer_roles,
            "role_order": self.role_order,
            "escalation_min_role": self.escalation_min_role,
        })
    }
}

enum Expect {
    Accept {
        user: &'static str,
        role: Option<&'static str>,
        escalated: bool,
        self_approved: bool,
    },
    Refuse(&'static str),
}

struct Spec {
    name: &'static str,
    description: &'static str,
    item: &'static str,
    /// The item's CURRENT digest when it differs from the published one.
    state_digest: Option<String>,
    waiting_on: (&'static str, Option<&'static str>),
    key: KeySpec,
    header_kid: Option<&'static str>,
    /// The action of the relayed request.
    action: &'static str,
    /// The action the person signed, when it differs from the request.
    signed_action: Option<&'static str>,
    signed_item_id: Option<&'static str>,
    /// The answer text relayed to TA.
    answer: Option<String>,
    /// The text `answer_sha256` was computed over, when not the relayed text.
    signed_answer: Option<String>,
    user: &'static str,
    role: Option<&'static str>,
    jti: &'static str,
    iat_off: i64,
    exp_off: i64,
    aud: &'static str,
    escalated: bool,
    self_approval_permitted: bool,
    presented_twice: bool,
    expect: Expect,
}

impl Spec {
    fn new(
        name: &'static str,
        item: &'static str,
        action: &'static str,
        user: &'static str,
        expect: Expect,
    ) -> Self {
        Self {
            name,
            description: "",
            item,
            state_digest: None,
            waiting_on: ("any_maintainer", None),
            key: KeySpec::default_key(),
            header_kid: None,
            action,
            signed_action: None,
            signed_item_id: None,
            answer: None,
            signed_answer: None,
            user,
            role: Some("admin"),
            jti: "jti-vector-0000",
            iat_off: 0,
            exp_off: 30,
            aud: INSTALL_ID,
            escalated: false,
            self_approval_permitted: false,
            presented_twice: false,
            expect,
        }
    }

    fn accept(user: &'static str, role: Option<&'static str>) -> Expect {
        Expect::Accept {
            user,
            role,
            escalated: false,
            self_approved: false,
        }
    }

    fn state_json(&self, it: &ItemDef) -> Value {
        json!({
            "id": it.id,
            "project": REPO,
            "item_digest": self.state_digest.clone().unwrap_or_else(|| it.digest()),
            "waiting_on": { "type": self.waiting_on.0, "value": self.waiting_on.1 },
            "requester_id": it.requester_id(),
            "agent_originated": it.provenance.is_some(),
        })
    }

    fn claims(&self, it: &ItemDef) -> Value {
        let action = self.signed_action.unwrap_or(self.action);
        let mut c = serde_json::Map::new();
        c.insert("user_id".into(), json!(self.user));
        c.insert("email".into(), json!(format!("{}@example.com", self.user)));
        c.insert("action".into(), json!(action));
        c.insert(
            "item_id".into(),
            json!(self.signed_item_id.unwrap_or(it.id)),
        );
        c.insert("project_id".into(), json!(REPO));
        c.insert("aud".into(), json!(self.aud));
        if let Some(r) = self.role {
            c.insert("role".into(), json!(r));
        }
        if self.escalated {
            c.insert("escalated".into(), json!(true));
        }
        if self.self_approval_permitted {
            c.insert("self_approval_permitted".into(), json!(true));
        }
        c.insert("item_digest".into(), json!(it.digest()));
        if action == "answer" {
            let text = self.signed_answer.as_ref().or(self.answer.as_ref());
            c.insert(
                "answer_sha256".into(),
                json!(sha256_tagged(
                    text.map(String::as_bytes).unwrap_or_default()
                )),
            );
        }
        c.insert("jti".into(), json!(self.jti));
        c.insert("iat".into(), json!(NOW + self.iat_off));
        c.insert("exp".into(), json!(NOW + self.exp_off));
        Value::Object(c)
    }

    fn expect_json(&self) -> Value {
        match &self.expect {
            Expect::Accept {
                user,
                role,
                escalated,
                self_approved,
            } => json!({
                "outcome": "accept",
                "verified": {
                    "user_id": user,
                    "action": self.action,
                    "role": role,
                    "escalated": escalated,
                    "self_approved": self_approved,
                },
            }),
            Expect::Refuse(reason) => json!({ "outcome": "refuse", "reason": reason }),
        }
    }

    fn to_json(&self, all: &[ItemDef], signer: &TestSigner) -> Value {
        let it = item(all, self.item);
        let header = json!({
            "alg": "EdDSA",
            "kid": self.header_kid.unwrap_or(self.key.kid),
        });
        let claims = self.claims(it);
        let assertion = signer.sign_with(&header, &claims);
        json!({
            "name": self.name,
            "status": "active",
            "description": self.description,
            "now": NOW,
            "install_id": INSTALL_ID,
            "registered_key": self.key.to_json(),
            "item": self.item,
            "item_state": self.state_json(it),
            "request": { "action": self.action, "answer": self.answer },
            "header": header,
            "claims": claims,
            "assertion": assertion,
            "presented_twice": self.presented_twice,
            "expect": self.expect_json(),
        })
    }
}

fn specs() -> Vec<Spec> {
    use Expect::{Accept, Refuse};
    let prov = "draft_review_with_provenance";
    let null = "draft_review_provenance_null";
    // user-123 is the requester recorded in `provenance`, so a different
    // signer ("alice") is the ordinary approver.
    let long_answer = "Use the main branch.".to_string();
    vec![
        // ── Accepted ────────────────────────────────────────────────────────
        Spec {
            description: "Approve an any_maintainer draft as an admin, with a role claim. The item has provenance and the signer is not its requester.",
            ..Spec::new("approve_with_provenance", prov, "approve", "alice", Spec::accept("alice", Some("admin")))
        },
        Spec {
            description: "Approve an item whose provenance is null: nothing to self-approve against, the digest is over provenance null.",
            ..Spec::new("approve_provenance_null", null, "approve", "alice", Spec::accept("alice", Some("admin")))
        },
        Spec {
            description: "Deny as an owner (owner is a maintainer role and outranks admin).",
            role: Some("owner"),
            ..Spec::new("deny_as_owner", prov, "deny", "bob", Spec::accept("bob", Some("owner")))
        },
        Spec {
            description: "Answer an agent question as the user it waits on. No role claim is needed for a user-addressed item; answer_sha256 covers the exact relayed text.",
            waiting_on: ("user", Some("user-123")),
            answer: Some(long_answer.clone()),
            role: None,
            ..Spec::new("answer_basic", "agent_question", "answer", "user-123", Spec::accept("user-123", None))
        },
        Spec {
            description: "Answer an item waiting on role member with an owner claim: rank-at-least under the default role order (member < admin < owner).",
            waiting_on: ("role", Some("member")),
            answer: Some(long_answer.clone()),
            role: Some("owner"),
            ..Spec::new("answer_role_rank_at_least", "agent_question", "answer", "carol", Spec::accept("carol", Some("owner")))
        },
        Spec {
            description: "Approve with the escalated claim set (an item escalated to the owner because nobody held the role). TA accepts it on an any_maintainer item and records escalated true.",
            role: Some("owner"),
            escalated: true,
            ..Spec::new("approve_escalated_claim", prov, "approve", "dana", Accept { user: "dana", role: Some("owner"), escalated: true, self_approved: false })
        },
        Spec {
            description: "Approve your own agent-originated item with self_approval_permitted true: accepted and recorded as self_approved.",
            self_approval_permitted: true,
            ..Spec::new("approve_self_approval_permitted", prov, "approve", "user-123", Accept { user: "user-123", role: Some("admin"), escalated: false, self_approved: true })
        },
        Spec {
            description: "A registered key with a non-default role order and maintainer role: claim 'lead' satisfies an item waiting on role 'editor' (viewer < editor < lead).",
            waiting_on: ("role", Some("editor")),
            key: KeySpec::custom_order(),
            role: Some("lead"),
            ..Spec::new("approve_custom_role_order", prov, "approve", "erin", Spec::accept("erin", Some("lead")))
        },
        Spec {
            description: "Unicode summary in NFC form. The digest is over the exact bytes of the canonical JSON, so this and the NFD vector have different digests; each is accepted for its own item.",
            ..Spec::new("approve_unicode_nfc", "unicode_summary_nfc", "approve", "alice", Spec::accept("alice", Some("admin")))
        },
        Spec {
            description: "Unicode summary in NFD form (same visible text as the NFC vector, different bytes, different digest).",
            jti: "jti-vector-0001",
            ..Spec::new("approve_unicode_nfd", "unicode_summary_nfd", "approve", "alice", Spec::accept("alice", Some("admin")))
        },
        Spec {
            description: "A summary of exactly 280 characters is kept whole.",
            ..Spec::new("approve_summary_280", "summary_exactly_280_chars", "approve", "alice", Spec::accept("alice", Some("admin")))
        },
        Spec {
            description: "A 281 character summary is TRUNCATED by TA to 277 characters plus '...' (280 total); it is not refused. The digest covers the truncated summary the feed publishes.",
            ..Spec::new("approve_summary_281_truncated", "summary_281_chars_truncated", "approve", "alice", Spec::accept("alice", Some("admin")))
        },
        Spec {
            description: "Provenance present but the excerpt text is the empty string: a different digest from provenance null and from a missing excerpt.",
            ..Spec::new("approve_empty_excerpt", "draft_review_empty_excerpt", "approve", "alice", Spec::accept("alice", Some("admin")))
        },
        Spec {
            description: "The answer has trailing whitespace and answer_sha256 was computed over the exact text including it. TA hashes the relayed answer untrimmed, so this is accepted.",
            waiting_on: ("user", Some("user-123")),
            answer: Some("Yes, go ahead.  \n".to_string()),
            role: None,
            ..Spec::new("answer_trailing_whitespace_exact_hash", "agent_question", "answer", "user-123", Spec::accept("user-123", None))
        },
        // ── Refused ─────────────────────────────────────────────────────────
        Spec {
            description: "exp is in the past at the fixed now (lifetime itself is fine).",
            iat_off: -100,
            exp_off: -70,
            ..Spec::new("refuse_expired", prov, "approve", "alice", Refuse("expired"))
        },
        Spec {
            description: "iat is more than 30 seconds in the future at the fixed now.",
            iat_off: 31,
            exp_off: 61,
            ..Spec::new("refuse_not_yet_valid", prov, "approve", "alice", Refuse("not_yet_valid"))
        },
        Spec {
            description: "exp is 61 seconds after iat: longer than the 60 second maximum.",
            exp_off: 61,
            ..Spec::new("refuse_bad_lifetime", prov, "approve", "alice", Refuse("bad_lifetime"))
        },
        Spec {
            description: "The same assertion presented twice: the first presentation is accepted, the second is refused as replayed (jti already used).",
            presented_twice: true,
            ..Spec::new("refuse_replayed_jti", prov, "approve", "alice", Refuse("replayed"))
        },
        Spec {
            description: "aud names a different TA install.",
            aud: OTHER_INSTALL_ID,
            ..Spec::new("refuse_wrong_audience", prov, "approve", "alice", Refuse("wrong_audience"))
        },
        Spec {
            description: "The item changed after the person saw it: the assertion signed the published digest, the item's current digest differs. Refused as item_changed and nothing is done.",
            state_digest: Some(item(&items(), prov).digest_with_summary("Add notes/live-run6.md (edited after review)")),
            ..Spec::new("refuse_item_changed", prov, "approve", "alice", Refuse("item_changed"))
        },
        Spec {
            description: "The person signed approve but the relayed request is deny.",
            signed_action: Some("approve"),
            ..Spec::new("refuse_wrong_action", prov, "deny", "alice", Refuse("claim_mismatch"))
        },
        Spec {
            description: "The assertion's item_id is a different item than the one being acted on.",
            signed_item_id: Some("att_draft_someone_else"),
            ..Spec::new("refuse_wrong_item", prov, "approve", "alice", Refuse("claim_mismatch"))
        },
        Spec {
            description: "answer_sha256 does not match the relayed answer (a swapped answer).",
            waiting_on: ("user", Some("user-123")),
            answer: Some("Use the release branch.".to_string()),
            signed_answer: Some(long_answer.clone()),
            role: None,
            ..Spec::new("refuse_answer_hash_mismatch", "agent_question", "answer", "user-123", Refuse("answer_changed"))
        },
        Spec {
            description: "The hash was computed over the TRIMMED answer but the relayed text keeps its trailing whitespace. TA does not trim before hashing, so the signer must hash exactly what is relayed.",
            waiting_on: ("user", Some("user-123")),
            answer: Some("Yes, go ahead.  \n".to_string()),
            signed_answer: Some("Yes, go ahead.".to_string()),
            role: None,
            ..Spec::new("refuse_answer_hash_over_trimmed_text", "agent_question", "answer", "user-123", Refuse("answer_changed"))
        },
        Spec {
            description: "The header kid is not registered. An unknown kid, a wrong algorithm and a bad signature are deliberately indistinguishable (one reason) so a probe learns nothing about which keys exist.",
            header_kid: Some("org-unknown"),
            ..Spec::new("refuse_unknown_kid", prov, "approve", "alice", Refuse("assertion_rejected"))
        },
        Spec {
            description: "The signer is the requester of an agent-originated item and the claim self_approval_permitted is absent.",
            ..Spec::new("refuse_self_approval_without_claim", prov, "approve", "user-123", Refuse("self_approval"))
        },
        Spec {
            description: "A member role cannot act on an any_maintainer item (maintainer_roles are admin and owner), even though it is signed correctly.",
            role: Some("member"),
            ..Spec::new("refuse_member_on_any_maintainer", prov, "approve", "alice", Refuse("not_permitted"))
        },
        Spec {
            description: "Custom role order viewer < editor < lead: a 'viewer' claim does not satisfy an item waiting on 'editor'.",
            waiting_on: ("role", Some("editor")),
            key: KeySpec::custom_order(),
            role: Some("viewer"),
            ..Spec::new("refuse_custom_role_order_too_low", prov, "approve", "erin", Refuse("not_permitted"))
        },
        // ── Rule 7: items rerouted away from a viewer ───────────────────────
        Spec {
            description: "Approve an item that was addressed to viewer-9 and rerouted by Wayfinder: the signer is another user (dana), escalated is true, and role 'member' meets the key's escalation_min_role (member). TA accepts and records escalated true.",
            waiting_on: ("user", Some("viewer-9")),
            role: Some("member"),
            escalated: true,
            ..Spec::new("approve_rerouted_viewer_item", prov, "approve", "dana", Accept { user: "dana", role: Some("member"), escalated: true, self_approved: false })
        },
        Spec {
            description: "Deny a rerouted item under the escalated claim with an owner role.",
            waiting_on: ("user", Some("viewer-9")),
            role: Some("owner"),
            escalated: true,
            ..Spec::new("deny_rerouted_viewer_item", prov, "deny", "dana", Accept { user: "dana", role: Some("owner"), escalated: true, self_approved: false })
        },
        Spec {
            description: "Answer an agent question that was rerouted from viewer-9 to dana under the escalated claim. answer_sha256 covers the exact relayed text.",
            waiting_on: ("user", Some("viewer-9")),
            answer: Some(long_answer),
            role: Some("admin"),
            escalated: true,
            ..Spec::new("answer_rerouted_viewer_item", "agent_question", "answer", "dana", Accept { user: "dana", role: Some("admin"), escalated: true, self_approved: false })
        },
        Spec {
            description: "A different user signs an item addressed to viewer-9 WITHOUT escalated: refused, the exception needs the escalated claim.",
            waiting_on: ("user", Some("viewer-9")),
            role: Some("owner"),
            ..Spec::new("refuse_rerouted_without_escalated_claim", prov, "approve", "dana", Refuse("not_permitted"))
        },
        Spec {
            description: "Escalated claim with a role below the key's escalation_min_role (custom order viewer < editor < lead, floor editor; claim 'viewer'): refused.",
            waiting_on: ("user", Some("viewer-9")),
            key: KeySpec::custom_order(),
            role: Some("viewer"),
            escalated: true,
            ..Spec::new("refuse_rerouted_role_below_escalation_floor", prov, "approve", "erin", Refuse("not_permitted"))
        },
        Spec {
            description: "Escalated claim with no role claim at all: refused, the floor cannot be checked.",
            waiting_on: ("user", Some("viewer-9")),
            role: None,
            escalated: true,
            ..Spec::new("refuse_rerouted_role_claim_absent", prov, "approve", "dana", Refuse("not_permitted"))
        },
        Spec {
            description: "The exception covers approve, deny and answer only. A signed 'apply' for a rerouted item is refused even with escalated true and an owner role.",
            waiting_on: ("user", Some("viewer-9")),
            role: Some("owner"),
            escalated: true,
            ..Spec::new("refuse_rerouted_wrong_action", prov, "apply", "dana", Refuse("not_permitted"))
        },
    ]
}

/// Placeholders other plan items fill in. They carry no `assertion` and no
/// `expect`, and the runner skips them, so they can never pass by accident.
/// None are open: rule 7's escalated viewer reroute is now active above.
fn pending() -> Vec<Value> {
    Vec::new()
}

fn notes() -> Vec<&'static str> {
    vec![
        "TEST ONLY. The private seed below is public on purpose so a signer on another system can reproduce these assertions. Never register this key with a real TA install and never reuse it anywhere else.",
        "This file is generated by TA's own code (crates/ta-daemon/src/attention/vectors.rs) and a TA test fails if the committed file differs from the regenerated output. Regenerate with: TA_REGENERATE_VECTORS=1 ./dev cargo test -p ta-daemon attention::vectors",
        "Each active vector is self-contained. To check a verifier: register registered_key (with test_key.public_key_b64) under install_id, evaluate at 'now' (a unix time, not the wall clock), build the item from item_state, present 'assertion' with request.action and request.answer, and compare with 'expect'. If presented_twice is true, the first presentation must be accepted and 'expect' describes the second.",
        "A refusal 'reason' is the `reason` field of the 403 body from POST /api/attention/{id}/act. Messages are human text and are not part of the contract; only the reason string is.",
        "item_digest is sha256 over the canonical JSON of {id, kind, summary, provenance, actions}. Canonical JSON means object keys sorted by byte order, no whitespace, UTF-8, strings escaped as serde_json does (only quote, backslash and control characters are escaped; every other character, including non-ASCII, is written as raw UTF-8). 'canonical_json' on each item is the exact string that was hashed.",
        "Unicode: TA does NOT normalize. It never converts a summary to NFC or NFD, so the NFC and NFD items have different digests. A signer must hash and sign exactly the bytes of the summary TA published in the feed and must not normalize it. The only text shaping TA does to a summary is: control characters become spaces, runs of whitespace (including Unicode whitespace such as U+00A0) collapse to one space, leading and trailing whitespace is removed, and the result is capped at 280 characters.",
        "Length: a summary of 280 characters is kept as is. A longer one is not refused: TA truncates it to the first 277 characters, removes trailing whitespace, and appends '...' (so at most 280). Lengths count Unicode scalar values (characters), not bytes. The digest covers the truncated summary, because that is what the feed publishes. 'summary_input' on an item shows the pre-shaping text when it differs.",
        "Answers: answer_sha256 is sha256 over the exact UTF-8 bytes of the relayed answer text. TA does not trim, normalize or re-encode the answer before hashing, so trailing whitespace and newlines count. An assertion whose hash was computed over trimmed text is refused with answer_changed when the relayed text is not trimmed.",
        "provenance null (no agent-side requester) and provenance with an empty-string excerpt are different values and have different digests.",
        "The signature is over the exact base64url header and claims segments as sent (header.claims). A signer may serialize the JSON with any key order; the verifier parses it. Signatures are Ed25519 and deterministic, so the compact assertions in this file are stable.",
        "role_order, maintainer_roles and escalation_min_role are the registered key's settings and are published by GET /api/attention metadata (keys[]). escalation_min_role is published by the feed and enforced by rule 7: for an item rerouted away from its named user, TA accepts a different signer only with escalated true, a role claim at or above this floor, and the action approve, deny or answer (the *_rerouted_* vectors).",
        "jti must be 8 to 128 characters. TA keeps used jtis for at least 300 seconds, so a replay inside an assertion's lifetime is always refused.",
    ]
}

/// The whole vectors document, built from TA's code.
fn generate() -> Value {
    let signer = TestSigner::from_seed(test_seed());
    let all = items();
    let mut vectors: Vec<Value> = specs().iter().map(|s| s.to_json(&all, &signer)).collect();
    vectors.extend(pending());
    json!({
        "format": "ta-attention-test-vectors/1",
        "contract": "docs/superpowers/specs/2026-10-11-attention-feed-and-human-assertions-contract.md",
        "generated_by": "crates/ta-daemon/src/attention/vectors.rs",
        "notes": notes(),
        "test_key": {
            "WARNING": "TEST ONLY. This key pair is published so another system can sign these vectors. Never register it with a real install.",
            "kid": KID,
            "alg": "EdDSA",
            "private_seed_hex": hex(&test_seed()),
            "public_key_b64": signer.public_b64(),
            "public_key_hex": signer.public_hex(),
            "fingerprint": ta_credentials::human::public_key_fingerprint(&signer.public_b64()),
        },
        "install_id": INSTALL_ID,
        "now": NOW,
        "items": all.iter().map(ItemDef::to_json).collect::<Vec<_>>(),
        "vectors": vectors,
    })
}

// ── Reading and running the committed file ──────────────────────────────────

fn pretty(v: &Value) -> String {
    let mut s = serde_json::to_string_pretty(v).expect("vectors serialize");
    s.push('\n');
    s
}

/// Parse the vectors file text. CRLF is normalized first so a checkout with
/// Windows line endings parses and compares the same.
fn parse_file_text(text: &str) -> Value {
    serde_json::from_str(&text.replace("\r\n", "\n")).unwrap_or_else(|e| {
        panic!(
            "{} is not valid JSON ({e}). Regenerate it with {REGEN_ENV}=1 ./dev cargo test -p ta-daemon attention::vectors",
            VECTORS_REL
        )
    })
}

fn load_committed() -> Value {
    let path = vectors_path();
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "cannot read {} ({e}). Generate it with {REGEN_ENV}=1 ./dev cargo test -p ta-daemon attention::vectors",
            path.display()
        )
    });
    parse_file_text(&text)
}

#[test]
fn committed_vectors_file_equals_generated_output() {
    let generated = generate();
    let path = vectors_path();
    if std::env::var(REGEN_ENV).is_ok_and(|v| v == "1") {
        std::fs::write(&path, pretty(&generated))
            .unwrap_or_else(|e| panic!("cannot write {}: {e}", path.display()));
        eprintln!("regenerated {}", path.display());
        return;
    }
    let committed = load_committed();
    assert!(
        committed == generated,
        "{} has drifted from what TA's code generates. If the change is intended, regenerate with \
         `{REGEN_ENV}=1 ./dev cargo test -p ta-daemon attention::vectors` and commit the file; the \
         Wayfinder side signs against it.",
        path.display()
    );
}

fn facts_from(state: &Value) -> ItemFacts {
    ItemFacts {
        id: state["id"].as_str().unwrap().to_string(),
        project: state["project"].as_str().unwrap().to_string(),
        digest: state["item_digest"].as_str().unwrap().to_string(),
        waiting_on_type: state["waiting_on"]["type"].as_str().unwrap().to_string(),
        waiting_on_value: state["waiting_on"]["value"].as_str().map(str::to_string),
        requester_id: state["requester_id"].as_str().map(str::to_string),
        agent_originated: state["agent_originated"].as_bool().unwrap(),
    }
}

fn strings(v: &Value) -> Vec<String> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|s| s.as_str().unwrap().to_string())
        .collect()
}

/// Run one active vector through the real verifier in a fresh temp state dir.
fn run_vector(file: &Value, v: &Value) -> Result<(), String> {
    let name = v["name"].as_str().unwrap_or("?");
    let dir = tempfile::tempdir().map_err(|e| format!("{name}: tempdir: {e}"))?;
    std::fs::write(
        dir.path().join("install-id"),
        v["install_id"].as_str().unwrap(),
    )
    .map_err(|e| format!("{name}: cannot write the install id: {e}"))?;
    let key = &v["registered_key"];
    let maintainers = strings(&key["maintainer_roles"]);
    let order = strings(&key["role_order"]);
    ta_credentials::human::add_assertion_key_full(
        dir.path(),
        key["kid"].as_str().unwrap(),
        file["test_key"]["public_key_b64"].as_str().unwrap(),
        Some(&maintainers),
        Some(&order),
        key["escalation_min_role"].as_str(),
        None,
    )
    .map_err(|e| format!("{name}: cannot register the key: {e}"))?;
    let verifier = Ed25519RegistryVerifier::new(dir.path().to_path_buf());
    let facts = facts_from(&v["item_state"]);
    let answer = v["request"]["answer"].as_str().map(str::to_string);
    let action = v["request"]["action"].as_str().unwrap();
    let now = v["now"].as_i64().unwrap();
    let token = v["assertion"].as_str().unwrap();
    let present = || {
        verifier.verify(
            token,
            &AssertionRequest {
                action,
                item: &facts,
                answer: answer.as_deref(),
            },
            now,
        )
    };
    if v["presented_twice"].as_bool() == Some(true) {
        present().map_err(|e| format!("{name}: the first presentation must be accepted: {e}"))?;
    }
    let result = present();
    let expect = &v["expect"];
    match (expect["outcome"].as_str(), result) {
        (Some("accept"), Ok(got)) => {
            let want = &expect["verified"];
            let actual = json!({
                "user_id": got.user_id,
                "action": got.action,
                "role": got.role,
                "escalated": got.escalated,
                "self_approved": got.self_approved,
            });
            if &actual == want {
                Ok(())
            } else {
                Err(format!(
                    "{name}: accepted but verified {actual}, expected {want}"
                ))
            }
        }
        (Some("accept"), Err(e)) => Err(format!(
            "{name}: expected accept, the verifier refused with reason '{}': {e}",
            assertion_code(&e)
        )),
        (Some("refuse"), Err(e)) => {
            let code = assertion_code(&e);
            let msg = e.to_string();
            if msg.trim().is_empty() || msg.contains('\u{2014}') {
                return Err(format!(
                    "{name}: the refusal message is empty or has an em dash"
                ));
            }
            if Some(code) == expect["reason"].as_str() {
                Ok(())
            } else {
                Err(format!(
                    "{name}: refused with reason '{code}', expected '{}'",
                    expect["reason"]
                ))
            }
        }
        (Some("refuse"), Ok(_)) => Err(format!(
            "{name}: expected refusal '{}' but the verifier accepted",
            expect["reason"]
        )),
        _ => Err(format!("{name}: expect.outcome must be accept or refuse")),
    }
}

#[test]
fn every_vector_runs_through_the_real_verifier() {
    let file = load_committed();
    let mut failures = Vec::new();
    let (mut ran, mut skipped) = (0, 0);
    let mut reasons = std::collections::BTreeSet::new();
    for v in file["vectors"].as_array().unwrap() {
        match v["status"].as_str() {
            Some("active") => {
                ran += 1;
                if let Some(r) = v["expect"]["reason"].as_str() {
                    reasons.insert(r.to_string());
                }
                if let Err(e) = run_vector(&file, v) {
                    failures.push(e);
                }
            }
            Some("pending") => {
                skipped += 1;
                assert!(
                    v.get("assertion").is_none() && v.get("expect").is_none(),
                    "pending vector '{}' must carry no assertion and no expectation until the plan item that owns it fills it in",
                    v["name"]
                );
                assert!(
                    v["pending_reason"].as_str().is_some_and(|r| !r.is_empty()),
                    "pending vector '{}' must say which plan item fills it in",
                    v["name"]
                );
            }
            other => failures.push(format!(
                "{}: status must be active or pending, got {other:?}",
                v["name"]
            )),
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {ran} vectors failed:\n{}",
        failures.len(),
        failures.join("\n")
    );
    assert!(ran >= 20, "expected at least 20 active vectors, ran {ran}");
    assert_eq!(skipped, 0, "no vector is pending any more");
    for r in REQUIRED_REASONS {
        assert!(
            reasons.contains(*r),
            "no negative vector covers the refusal reason '{r}'"
        );
    }
}

#[test]
fn published_digests_recompute_from_the_published_canonical_json() {
    let file = load_committed();
    for it in file["items"].as_array().unwrap() {
        let canonical = it["canonical_json"].as_str().unwrap();
        assert_eq!(
            sha256_tagged(canonical.as_bytes()),
            it["item_digest"].as_str().unwrap(),
            "item {} digest does not match its canonical_json",
            it["name"]
        );
        // The canonical string is itself canonical: re-canonicalizing is a no-op.
        let reparsed: Value = serde_json::from_str(canonical).unwrap();
        assert_eq!(canonical_json(&reparsed), canonical, "item {}", it["name"]);
    }
}

#[test]
fn item_edge_cases_behave_as_the_notes_state() {
    let file = load_committed();
    let find = |name: &str| {
        file["items"]
            .as_array()
            .unwrap()
            .iter()
            .find(|i| i["name"] == name)
            .unwrap_or_else(|| panic!("missing item {name}"))
            .clone()
    };
    // NFC and NFD: same visible text, no normalization, different digests.
    let (nfc, nfd) = (find("unicode_summary_nfc"), find("unicode_summary_nfd"));
    assert_ne!(nfc["summary"], nfd["summary"]);
    assert_ne!(nfc["item_digest"], nfd["item_digest"]);
    assert!(nfc["summary"].as_str().unwrap().contains('\u{e9}'));
    assert!(nfd["summary"].as_str().unwrap().contains("e\u{301}"));
    // 280 kept whole; 281 truncated to 277 + "..." and not refused.
    let kept = find("summary_exactly_280_chars");
    assert_eq!(kept["summary_chars"], 280);
    assert!(kept.get("summary_input").is_none());
    let cut = find("summary_281_chars_truncated");
    assert_eq!(cut["summary_input_chars"], 281);
    assert_eq!(cut["summary_chars"], 280);
    assert!(cut["summary"].as_str().unwrap().ends_with("..."));
    // Null provenance and an empty excerpt are distinct values.
    let null = find("draft_review_provenance_null");
    let empty = find("draft_review_empty_excerpt");
    assert!(null["provenance"].is_null());
    assert_eq!(empty["provenance"]["excerpt"]["text"], "");
    assert_ne!(null["item_digest"], empty["item_digest"]);
}

#[test]
fn the_vectors_file_has_no_em_dashes_and_marks_the_key_test_only() {
    let text = std::fs::read_to_string(vectors_path()).unwrap();
    assert!(!text.contains('\u{2014}'), "no em dashes anywhere");
    let file = parse_file_text(&text);
    assert!(file["test_key"]["WARNING"]
        .as_str()
        .unwrap()
        .starts_with("TEST ONLY"));
    assert!(file["notes"][0].as_str().unwrap().starts_with("TEST ONLY"));
}

#[test]
fn crlf_line_endings_in_the_vectors_file_parse_to_the_same_document() {
    let text = std::fs::read_to_string(vectors_path()).unwrap();
    let crlf = text.replace("\r\n", "\n").replace('\n', "\r\n");
    assert_eq!(parse_file_text(&crlf), parse_file_text(&text));
}
